package app.unifeed.media; import java.time.Duration; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.http.CacheControl; import org.springframework.web.servlet.config.annotation.*; @Configuration public class MediaWebConfig implements WebMvcConfigurer {private final String root;public MediaWebConfig(@Value("${app.storage.uploads-root:uploads}")String r){root=r;}public void addResourceHandlers(ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations("file:"+java.nio.file.Path.of(root).toAbsolutePath()+"/").setCacheControl(CacheControl.maxAge(Duration.ofDays(365)).cachePublic().immutable());}}
